// Authoritative offline Scripture for daily verses and every landing-page
// passage. Generated by scripts/build-verse-bundle.mjs, one lazy chunk per
// language; no account, API request, or generated Scripture wording is needed.
import { usfmFromReference } from './bibleRef';

const loaders = import.meta.glob('../content/verses/*.json');
const cache = new Map();

function loadLang(lang) {
  if (!cache.has(lang)) {
    const loader = loaders[`../content/verses/${lang}.json`];
    cache.set(lang, loader
      ? loader().then((module) => module.default).catch(() => null)
      : Promise.resolve(null));
  }
  return cache.get(lang);
}

export async function getBundledVerse({ reference, lang, usfm }) {
  const passage = usfm || usfmFromReference(reference);
  const match = /^([A-Z0-9]{3})\.(\d+)(?:\.(\d+)(?:-(\d+))?)?$/.exec(String(passage || ''));
  if (!match) return null;
  const [, book, chapterString, startString, endString] = match;
  const chapter = Number(chapterString);
  const start = Number(startString);
  const end = Number(endString || startString);
  if (chapter < 1 || (startString && (start < 1 || end < start || end > 176))) return null;

  const data = await loadLang(lang);
  if (!data) return null;

  let text;
  if (!startString) {
    // A sparse collection of individual verses cannot prove chapter completeness.
    // Only chapters explicitly saved in full by the generator may resolve here.
    text = data[`${book} ${chapter}`];
  } else {
    const extent = start === end ? start : `${start}-${end}`;
    text = data[`${book} ${chapter}:${extent}`];
    if (text) return { text, ref: reference || passage, source: 'bundle' };
    const verses = [];
    for (let verse = start; verse <= end; verse++) {
      const part = data[`${book} ${chapter}:${verse}`];
      // Never present a truncated range as the complete cited passage.
      if (!part) return null;
      verses.push(part);
    }
    text = verses.join(' ');
  }
  return text ? { text, ref: reference || passage, source: 'bundle' } : null;
}
